// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/catalog", wrapper.GetCatalog)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/match-rooms", wrapper.CreateMatchRoom)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/match-rooms/{roomID}/match", wrapper.DeleteMatch)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/match-rooms/{roomID}/match", wrapper.CreateMatch)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/match-rooms/{roomID}/rematch", wrapper.Rematch)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/match-rooms/{roomID}/match/state", wrapper.GetMatchState)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/match-rooms/{roomID}/match/turn-commands", wrapper.SubmitTurnCommand)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/match-rooms/{roomID}/match/cpu-status/consume", wrapper.ConsumeCPUStatus)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/match-rooms/{roomID}/match/reset", wrapper.ResetTurn)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/match-rooms/{roomID}/match/resolve", wrapper.ResolveTurn)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/match-rooms/{roomID}/match/surrender", wrapper.Surrender)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/match-rooms/{roomID}/match/config", wrapper.GetMatchConfig)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/match-rooms/{roomID}/match/allowed-tiles", wrapper.GetAllowedTiles)

	return m
}

